document.addEventListener('click',event=>{
  const target=event.target.closest('[data-rank-view],[data-rank-subject],[data-action="reset-quiz-cycle"]');if(!target)return;
  event.preventDefault();event.stopImmediatePropagation();
  if(target.dataset.rankView){state.rankView=target.dataset.rankView;render();return}if(target.dataset.rankSubject){startRankedSubject(target.dataset.rankSubject);return}
  if(!fullAccess()){promptSubscription('You have used all questions in your free question bank for this selection. Subscribe to unlock all sources.');return;}
  const key=quizPoolKey(state.quizSetup);state.quizCycles=resetQuizCycle(state.quizCycles,key);put('quizCycles',state.quizCycles);render();
},true);
