  return [...grouped.entries()].map(([threadUid,messages])=>{const latest=messages[messages.length-1],user=state.users.find(item=>item.uid===threadUid),participant=messages.find(item=>item.senderUid!==state.nativeUid),name=user?.name||participant?.senderName||participant?.senderEmail||'User',email=user?.email||participant?.senderEmail||'';return{threadUid,messages,latest,name,email}}).sort((a,b)=>Number(b.latest.createdAt||0)-Number(a.latest.createdAt||0));
