  const messages=state.messages.filter(message=>message.threadUid===state.messageThreadUid),user=state.users.find(item=>item.uid===state.messageThreadUid),participant=messages.find(item=>item.senderUid!==state.nativeUid),name=user?.name||participant?.senderName||participant?.senderEmail||'New conversation',email=user?.email||participant?.senderEmail||'';
