function exportSavedExam(exam){
 if(!premiumAccess()&&!state.printableExamUnlocked){promptSubscription();return;}
 try{const bytes=createExamDocx(exam.questions,exam.options),filename=examFilename(exam);
 if(window.NativeBridge&&!window.ESAS_WEB){let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));NativeBridge.savePrintableExam(filename,btoa(binary));}
 else{const url=URL.createObjectURL(new Blob([bytes],{type:DOCX_MIME})),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
 }catch(error){showNotice(error.message,'Exam export');}
}
