document.addEventListener('submit',event=>{
  const form=event.target;if(!['exam-form','exam-payment-form'].includes(form.id))return;
  event.preventDefault();event.stopImmediatePropagation();const data=new FormData(form);
  if(form.id==='exam-payment-form'){
    if(!state.nativeUid||!window.NativeBridge||!state.supportEnabled)return;
    NativeBridge.submitExamPayment(String(data.get('reference')||'').trim());return;
  }

  const selectedSubjects=data.getAll('subjects'),selectedSources=data.getAll('sources');
  if(!selectedSubjects.length||!selectedSources.length){showNotice('Select at least one subject and one source.');return;}
  if(!premiumAccess()&&!state.printableExamUnlocked){const pool=examQuestions(availableQuestions(),{subjects:selectedSubjects,sources:selectedSources,type:data.get('type')}),used=new Set(savedExams().flatMap(e=>e.questions.map(examItemKey))),reserved=new Set(state.quizLibrary.flatMap(e=>(e.session?.ids||[]).filter(id=>e.session?.answers?.[id]!==undefined)));const remaining=pool.filter(q=>!used.has(examItemKey(q))&&!reserved.has(q.id)).length;promptSubscription(!fullAccess()&&!remaining?'You have used all questions in your free question bank for these sources. Subscribe to unlock all sources.':'Printable Word exams require Premium or an existing printable purchase. Choose a subscription to unlock all sources.');return;}
  const filters={subjects:selectedSubjects,sources:selectedSources,type:data.get('type')},count=Number(data.get('count')),setCount=Number(data.get('setCount'));
  if(!Number.isInteger(count)||count<1){showNotice('Enter a positive whole number of questions.');return;}
  try{
    const previous=readExamLibrary(localStorage,state.nativeUid),parent=normalizeExamPath(data.get('folder'));
    if(!parent.length)throw Error('Enter an exam folder.');
    if(parent.length>=6)throw Error('Use at most five folder levels here to leave room for the set subfolder.');
    const pool=examQuestions(questionBank,filters),manual=data.get('selectionMode')==='manual';
    const used=new Set(previous.filter(x=>sameExamPath(examParentPath(x),parent)).flatMap(x=>x.questions.map(examItemKey)));
    const candidates=manual?selectManualExamQuestions(questionBank,examWorkspace().manual.selected,{count,setCount,mode:data.get('setMode')}):data.get('setMode')==='different'&&data.get('excludeSaved')?pool.filter(q=>!used.has(examItemKey(q))):pool;
    const options=Object.fromEntries(['title','institution','department','course','set','columns','paperSize'].map(k=>[k,data.get(k)]));
    if(setCount>1&&options.set==='A')options.set='';
    const subjectCounts=manual?null:Object.fromEntries(selectedSubjects.map(id=>[id,Number(data.get('subjectCount:'+id)??(selectedSubjects.length===1?count:0))]));
    const sets=createExamSets(candidates,{count,setCount,subjectCounts,mode:data.get('setMode'),randomize:!!data.get('random'),options,distribution:{mode:data.get('answerLayout'),counts:['A','B','C','D'].map(k=>Number(data.get('answer'+k)))}}).map(exam=>({...exam,folderPath:[...parent,`Set ${exam.options.set}`],filters,selectionMode:manual?'manual':'automatic'}));
    for(const exam of sets)normalizeExamPath(exam.folderPath);
    storeExams([...sets,...previous]);examWorkspace().path=sets[0].folderPath;state.examPreviewId=sets[0].id;render();
  }catch(error){showNotice(error.message,'Exam documents');}

},true);

function sourceTreeMarkup(sources, leaf, selectable=false){
  const organization=state.page==='source-organizer'?(state.sourceOrgDraft||state.sourceOrganization):state.sourceOrganization;
  const tree=buildSourceTree(sources,organization);
  const branch=node=>node.folders.map(folder=>{const ids=folderSourceIds(folder),expanded=state.sourceExpanded[folder.key]??(state.page!=='reviewer'),selected=ids.filter(id=>state.quizSetup.sources.includes(id)).length;return `<section class="source-tree-folder"><div class="source-tree-heading"><button type="button" class="source-tree-toggle grow" data-source-expand="${esc(folder.key)}" aria-expanded="${expanded}"><span>${expanded?'⌄':'›'}</span><span class="source-folder-icon">${uiIcon('folder')}</span><strong>${esc(folder.label)}</strong><small>${ids.length} sources</small></button>${selectable?`<button type="button" class="folder-select ${selected===ids.length?'selected':''}" data-source-group="${esc(folder.key)}" aria-label="Select sources in ${esc(folder.label)}" aria-pressed="${selected===ids.length}">${selected===ids.length?'✓':selected?'−':'＋'}</button>`:''}</div><div class="source-tree-children" ${expanded?'':'hidden'}>${branch(folder)}</div></section>`;}).join('')+node.sources.map(leaf).join('');
  return `<div class="source-tree">${branch(tree)}</div>`;
}
