  if(target.dataset.sourceGroup){event.preventDefault();event.stopImmediatePropagation();const pool=state.page==='reviewer'?availableQuestions():availableQuestions().filter(q=>state.quizSetup.subjects.includes(q.subject)),allowed=new Set(pool.map(q=>q.sourceId)),tree=buildSourceTree(sourceRegistry.filter(s=>allowed.has(s.id)),state.sourceOrganization);const find=node=>node.key===target.dataset.sourceGroup?node:node.folders.map(find).find(Boolean);const folder=find(tree);if(!folder)return;const ids=folderSourceIds(folder),selected=new Set(state.quizSetup.sources);if(ids.every(id=>selected.has(id)))ids.forEach(id=>selected.delete(id));else ids.forEach(id=>selected.add(id));if(!selected.size&&state.page!=='reviewer'){showNotice('Keep at least one source selected.');return;}state.quizSetup.sources=[...selected];render();return;}
  if(target.dataset.sourceReorder){event.preventDefault();event.stopImmediatePropagation();if(!ownerPreview())return;const entries=collectSourceOrganization(),entry=entries.find(x=>x.id===target.dataset.sourceReorder),siblings=entries.filter(x=>JSON.stringify(x.path)===JSON.stringify(entry.path)).sort((a,b)=>a.order-b.order||sourceRegistry.find(s=>s.id===a.id).title.localeCompare(sourceRegistry.find(s=>s.id===b.id).title,undefined,{numeric:true}));const index=siblings.indexOf(entry),other=index+(target.dataset.direction==='up'?-1:1);if(other>=0&&other<siblings.length)[siblings[index],siblings[other]]=[siblings[other],siblings[index]];siblings.forEach((x,i)=>x.order=i);state.sourceOrgDraft=entries;render();return;}
  if(target.dataset.openQuiz){event.preventDefault();event.stopImmediatePropagation();const entry=state.quizLibrary.find(x=>x.id===target.dataset.openQuiz);if(!entry)return;archiveActiveQuiz();if(entry.status==='Completed'){state.lastResult=entry.result;put('lastResult',state.lastResult);go('results');}else{const available=new Set(availableQuestions().map(q=>q.id));if(entry.session.ids.some(id=>!available.has(id))){showNotice('Some questions are unavailable or access has expired. Create a new quiz with your current sources.');return;}state.session={...entry.session,answers:{...entry.session.answers},segmentStartedAt:Date.now(),startedAt:null};saveSession();go('active-quiz');}return;}
