function tournamentRows(rows){return rows.map((row,i)=>`<div class="action-row"><strong>${i+1}</strong><span class="grow">${esc(row.name||'Learner')}</span><strong>${row.score}/${row.total}</strong><span>${formatElapsed(row.elapsedMs)}</span></div>`).join('')||'<p class="small muted">Results appear after the contest closes.</p>';}
function tournamentHome(){const d=state.tournamentStatus;return `${title('Tournaments','COMPETE · RANK UP · WIN REWARDS','home')}${tournamentCard()}<div class="glass pad"><p>Open to every registered account, including Free. One try per tournament. Leaving, refreshing or putting the app in the background uses your attempt.</p><p>Rankings use correct answers, then completion time. All entrants receive the same number of items. Rewards are Premium access days.</p>${d?.result?`<div class="notice">Your result: ${d.result.score}/${d.result.total} · ${formatElapsed(d.result.elapsedMs)}</div>`:''}<button class="btn secondary wide" data-tournament-refresh>Refresh leaderboard</button></div><div class="section-head" id="full-leaderboard"><h2>Full leaderboard</h2></div>${tournamentRows(d?.entries||[])}`;}

function tournamentActive(){const a=state.tournamentAttempt;if(!a)return tournamentHome();const q=a.questions[a.index];return `<div class="quiz-head"><strong>Tournament</strong><span>Question ${a.index+1} / ${a.questions.length}</span></div><p class="notice">Stay on this screen. Leaving invalidates your only attempt.</p><div class="glass question-card"><span class="tag">${esc(q.type)}</span><h2>${esc(q.prompt)}</h2>${questionMediaHtml(q)}${q.choices.map((choice,i)=>`<button class="choice ${a.answers[q.id]===i?'selected':''}" data-tournament-answer="${i}" ${state.tournamentBusy?'disabled':''}><span class="choice-letter">${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'[i]}</span><span>${esc(choice)}</span></button>`).join('')}</div><div class="sticky-actions"><button class="btn secondary" data-tournament-prev ${!a.index||state.tournamentBusy?'disabled':''}>Previous</button><button class="btn" data-tournament-next ${state.tournamentBusy?'disabled':''}>${a.index===a.questions.length-1?'Submit exam':'Next →'}</button></div>`;}
function invalidateTournament(){if(!state.tournamentAttempt&&!state.tournamentJoining)return;const tournamentId=state.tournamentAttempt?.tournamentId;state.tournamentCancelled=true;put('tournamentActive',null);state.tournamentAttempt=null;state.tournamentJoining=false;state.tournamentBusy=false;NativeBridge.tournamentCall(JSON.stringify({action:'invalidate',tournamentId}));state.page='tournaments';}
window.esasNative.tournament=function(result){const d=JSON.parse(result);if(d.error){if(d.action==='status'){state.tournamentStatusError=d.error;render();return;}state.bulkGrantBusy=false;state.tournamentBusy=false;state.tournamentJoining=false;showNotice(d.error,'Tournament');return}if(d.action==='grantAllPro'){if(d.operationId!==get('bulkGrant.'+state.nativeUid,null))return;if(!ownerEligible())return;if(d.done){put('bulkGrant.'+state.nativeUid,null);state.bulkGrantBusy=false;NativeBridge.loadUsers();showNotice(`Granted +1 day Pro to ${d.granted} accounts. Existing Premium benefits were kept.`,'Grant complete');}else{state.bulkGrantBusy=true;NativeBridge.tournamentCall(JSON.stringify({action:'grantAllPro',operationId:d.operationId}));}return;}if(d.action==='activatePlan'){NativeBridge.loadAccountData();showNotice('30-day plan activated after payment verification.','Plan activated');return}if(['create','settle','stop'].includes(d.action)){loadTournament();showNotice(d.action==='create'?'Tournament started. Every account can join once.':d.action==='stop'?'Tournament stopped. Rewards are finalizing.':'Rankings and rewards finalized.','Tournament');return}if(d.action==='status'){state.tournamentStatusError='';state.tournamentStatus=d;render();return}if(d.action==='start'){state.tournamentJoining=false;state.tournamentBusy=false;state.tournamentAttempt={...d,index:0,answers:{}};put('tournamentActive',{uid:state.nativeUid,tournamentId:d.tournamentId});if(state.tournamentCancelled||document.hidden||!['home','tournaments'].includes(state.page)){invalidateTournament();render();return}go('tournament-active');return}if(d.action==='submit'){put('tournamentActive',null);state.tournamentAttempt=null;state.tournamentBusy=false;go('tournaments');showNotice(`You scored ${d.score}/${d.total} in ${formatElapsed(d.elapsedMs)}. Rankings and rewards are finalized after the tournament closes.`,'Exam submitted');return}if(d.action==='invalidate'){state.tournamentStatus={...(state.tournamentStatus||{}),day:d.day,status:'invalid'};if(state.page==='tournament-active')state.page='tournaments';render();}};
document.addEventListener('click',event=>{const t=event.target.closest('[data-tournament-start],[data-tournament-refresh],[data-tournament-answer],[data-tournament-prev],[data-tournament-next]');if(!t)return;event.stopImmediatePropagation();event.preventDefault();if(publicConfig.tournamentsEnabled!==true)return;if(t.hasAttribute('data-tournament-refresh')){loadTournament();return}if(t.hasAttribute('data-tournament-start')){if(state.tournamentBusy)return;state.tournamentCancelled=false;state.tournamentBusy=true;state.tournamentJoining=true;render();NativeBridge.tournamentCall(JSON.stringify({action:'start'}));return}const a=state.tournamentAttempt;if(!a||state.tournamentBusy)return;if(t.hasAttribute('data-tournament-answer'))a.answers[a.questions[a.index].id]=Number(t.dataset.tournamentAnswer);else if(t.hasAttribute('data-tournament-prev'))a.index=Math.max(0,a.index-1);else if(a.index<a.questions.length-1)a.index++;else {if(Object.keys(a.answers).length!==a.questions.length){showNotice('Answer every question before submitting.','Tournament');return}state.tournamentBusy=true;NativeBridge.tournamentCall(JSON.stringify({action:'submit',tournamentId:a.tournamentId,answers:a.answers}));}render();},true);
