async function configureOffline(){
 if(!window.ESAS_WEB||!('serviceWorker' in navigator))return;
 try{if(premiumAccess())await navigator.serviceWorker.register('./offline-worker.js');
 else{for(const registration of await navigator.serviceWorker.getRegistrations())if(registration.active?.scriptURL.endsWith('/offline-worker.js'))await registration.unregister();for(const key of await caches.keys())if(key.startsWith('esas-premium-'))await caches.delete(key);}}
 catch(error){console.warn('Offline setup failed',error.message);}
}
